        GraphError::Manifest(ManifestError::Parse {
            path: pyproject_path.to_path_buf(),
            format: ManifestFormat::PyprojectToml,
            message: e.to_string(),
        })
    })?;
    Ok(Some(val))
}

/// Extracts `[tool.maturin].targets` from an already-parsed `pyproject.toml`
